-- Tune taxonomy RLS policies and indexes after initial import.
drop policy if exists "Editors manage categories" on public.mcms_categories;
drop policy if exists "Editors can insert categories" on public.mcms_categories;
drop policy if exists "Editors can update categories" on public.mcms_categories;
drop policy if exists "Admins can delete categories" on public.mcms_categories;
create policy "Editors can insert categories" on public.mcms_categories for insert to authenticated with check (private.mcms_has_workspace_role(workspace_id,array['owner'::public.mcms_workspace_role,'admin'::public.mcms_workspace_role,'editor'::public.mcms_workspace_role,'publisher'::public.mcms_workspace_role]));
